import {
	copyFileSync,
	existsSync,
	mkdirSync,
	readdirSync,
} from "fs";
import { dirname, join } from "path";

export function findCapsuleAppBundle(
	capsuleNetwork: {
		capsulesRootDir?: string;
		graphCapsules?: {
			getCapsuleIgnoreVersion(id: { toStringWithoutVersion(): string }): { path: string } | undefined;
		};
	} | undefined,
	componentId: { toStringWithoutVersion(): string },
): string | undefined {
	if (!capsuleNetwork) return undefined;

	const capsule =
		capsuleNetwork.graphCapsules?.getCapsuleIgnoreVersion(componentId);
	if (capsule) {
		const dir = join(capsule.path, "artifacts", "app-bundle");
		if (existsSync(dir)) return dir;
	}

	const rootDir = capsuleNetwork.capsulesRootDir;
	if (!rootDir || !existsSync(rootDir)) return undefined;
	const idPrefix = componentId
		.toStringWithoutVersion()
		.replace(/\//g, "_")
		.replace(/\./g, "_");
	const entries = readdirSync(rootDir, { withFileTypes: true });
	for (const e of entries) {
		if (!e.isDirectory()) continue;
		const normalized = e.name.replace(/\./g, "_");
		if (!normalized.startsWith(idPrefix)) continue;
		const dir = join(rootDir, e.name, "artifacts", "app-bundle");
		if (existsSync(dir)) return dir;
	}
	return undefined;
}

export function copyDirRecursive(
	srcDir: string,
	destDir: string,
	relBase = "",
): { entry?: string } {
	let entry: string | undefined;
	const entries = readdirSync(srcDir, { withFileTypes: true });
	for (const e of entries) {
		const srcPath = join(srcDir, e.name);
		const rel = relBase ? `${relBase}/${e.name}` : e.name;
		if (e.isDirectory()) {
			const sub = copyDirRecursive(srcPath, destDir, rel);
			if (!entry && sub.entry) entry = sub.entry;
		} else {
			const target = join(destDir, rel);
			mkdirSync(dirname(target), { recursive: true });
			copyFileSync(srcPath, target);
			if (
				!entry &&
				rel.endsWith(".cjs") &&
				!rel.endsWith(".cjs.map") &&
				!rel.endsWith(".map.cjs")
			) {
				entry = rel.split("/").pop();
			}
		}
	}
	return { entry };
}
